import { Query } from '../query.js';
import * as cqn from '../cqn'

export class XSERT extends Query {
  static entries(...args: any[]): XSERT;
  static into(x: any, ...tail: any[]): XSERT;
  into(...args: any[]): this;
  entries(...args: any[]): this;
  columns(...args: any[]): this;
  values(...args: any[]): this;
  rows(...args: any[]): this;
  from(...args: any[]): this;
}
export class INSERT extends XSERT {
  INSERT: cqn.INSERT;
}
export class UPSERT extends XSERT {
  UPSERT: cqn.UPSERT;
}
